    let newNode = new Node(newData);

    // Make next of new node as head
    newNode.next = head;

    // Change prev of head node to new node
    if (head !== null) {
        head.prev = newNode;
    }

    // Return the new node as the head of the doubly linked list
    return newNode;
}

